export const ruAbout3: Record<string, string> = {
	'amrita-institute-of-medical-sciences-kochi':
		"##history\nAmrita Hospital в Ponekkara (Кочи), ранее Amrita Institute of Medical Sciences (AIMS), основан 17 мая 1998 года Mata Amritanandamayi Devi (Amma) как многопрофильная больница третичного уровня и учебное учреждение. В 2013 году получил FICCI National Healthcare Excellence Award как лучшая больница страны, а в 2016 году — ещё две премии FICCI за безопасность пациентов и инновации в медицинских технологиях. Аккредитован NABH, лаборатории аккредитованы NABL.\n##specialities\nБольница располагает 29 профильными отделениями и 17 центрами передового опыта, около 670 преподавателями-клиницистами и 4000 сотрудниками вспомогательного персонала, обслуживает более миллиона амбулаторных визитов и более 70 000 госпитализаций в год. Среди достижений — первая в Керале одновременная трансплантация поджелудочной железы и почки (2014), первая в Южной Азии двусторонняя трансплантация рук (2015), а в 2021 году — первая трансплантация обеих верхних конечностей с использованием технологии сохранения трансплантата HEMO2life, девятая такая операция для больницы. Услуги варьируются от трансфузионной медицины и урологии до черепно-челюстно-лицевой хирургии, дерматологии и косметологии.\n##technology\nБольница располагает от примерно 1100 до 1450 коек по данным разных источников, что делает её одной из крупнейших в Южной Индии. Находится на обширном кампусе в Ponekkara, Кочи.\n##international\nAmrita располагает отдельной командой, координирующей лечение иностранных пациентов, с поддержкой по медицинской визе и проживанию, предварительными медицинскими заключениями по лечению и стоимости, а также многоязычным переводом.",
	'aster-medcity':
		"##history\nAster Medcity в Cheranalloor (Кочи) основана Aster DM Healthcare в 2013 году и начала работу в режиме мягкого запуска в 2014 году. Расположена на кампусе площадью 40 акров на берегу бэкуотеров Кочи, является одним из крупнейших центров четвертичной помощи в Южной Азии. Стала первой в Керале многопрофильной больницей четвертичного уровня, аккредитованной JCI, а в первый же год также получила аккредитацию NABH, сертификат качества сестринского ухода NABH и сертификат Green OT.\n##specialities\nAster Medcity — многопрофильная больница с восемью центрами передового опыта, включая неврологию, кардиологию, ортопедию, онкологию, гастроэнтерологию, нефрологию, урологию, женское здоровье, педиатрию, неонатологию и многоорганную трансплантацию. Мультидисциплинарная команда трансплантологии, включающая гепатологов, нефрологов, хирургов-трансплантологов и реаниматологов, занимается трансплантацией почек, печени, сердца и комбинированными трансплантациями. Сообщается, что больница стала первой в Керале, предложившей роботизированную хирургию минимального доступа с системой da Vinci, с более чем 5000 операций с помощью робота в трансплантологии, урологии и гинекологии.\n##technology\nБольница — крупное учреждение четвертичной помощи с несколькими сотнями коек; источники указывают от примерно 670 до 800. Кампус спроектирован с заботой о комфорте пациентов, имеет экологическую сертификацию.\n##international\nAster Medcity — известное направление для медицинских путешественников из Южной Индии. Cheranalloor находится рядом с городом Кочи, примерно в 25–30 км от международного аэропорта Кочин.",
	'lakeshore-hospital':
		"##history\nVPS Lakeshore Hospital в Nettoor (Кочи), на объездной дороге NH-66, — многопрофильная больница узкой специализации, начавшая работу как многопрофильная больница в январе 2003 года. Аккредитована NABH, её описывают как ведущее направление медицинского туризма. Получила премию правительства штата Керала за лучшую больницу для медицинского туризма в 2014 году, премию Worldwide Achievers за лучшую больницу Кералы в 2016 году и премию Times of India за лучшую больницу в онкологических услугах в 2017 году.\n##specialities\nБольница располагает более чем 30 клиническими отделениями, включая многоорганную трансплантацию, гастроэнтерологию, эндопротезирование суставов, кардиологию, сердечно-сосудистую хирургию и неврологию. Отделение нефрологии и трансплантации почек провело более 1600 трансплантаций, а центр кардиологии включает трансплантацию сердца и ЭКМО. Среди достижений — первая трансплантация печени в Керале, первая детская трансплантация костного мозга, первая в штате роботизированная система эндопротезирования коленного сустава и первая в Керале служба воздушной, водной и наземной скорой помощи, признанная Limca Book of Records.\n##technology\nБольница располагает несколькими сотнями коек, источники указывают от примерно 470 до 650, лидирует в трансплантации органов, кардиологической помощи и малоинвазивной хирургии.\n##international\nБольница предлагает круглосуточное обслуживание гостей, варианты предоплаты для иностранных пациентов, индивидуальное меню, многоязычный персонал и приём иностранной валюты.",
	'kims-health-kochi':
		"##history\nKIMS Health, Кочи — больница группы учреждений KIMS со штаб-квартирой в Тируванантапураме, у которой также есть больницы на Ближнем Востоке. Больница и хирургический центр расположены в Pathadipalam, Changampuzha Nagar Post, Edappally, и стремятся предоставлять медицинскую помощь мирового уровня по доступным ценам. Аккредитована NABH и Australian Council on Healthcare Standards International (ACHSI).\n##specialities\nБольница является многопрофильным учреждением на 125 коек с около 25 отделениями, охватывающими разные заболевания и недомогания. Предлагает амбулаторные и стационарные отделения, лабораторию, аптеку, рентген, ЭКГ и круглосуточные услуги при поддержке опытных консультантов, обученного сестринского персонала и парамедиков.\n##technology\nБольница современна и хорошо оснащена для своего размера. По сравнению с крупнейшими больницами Кочи это меньшее учреждение, поэтому пациентам с очень сложными потребностями, например многоорганной трансплантацией, возможно, лучше обратиться в другое место.\n##international\nEdappally — оживлённый район Кочи, недалеко от торгового центра Lulu Mall и железнодорожной станции Edappally. Удобное расположение и умеренный размер делают больницу подходящей для пациентов, которым нужны обычные или плановые процедуры в комфортных условиях.",
	'apollo-multispeciality-hospitals-kolkata':
		"##history\nApollo Multispeciality Hospitals, ранее Apollo Gleneagles, на Canal Circular Road в Калькутте, основана в 2003 году, это больница третичного уровня на 700–750 коек. Единственная больница Восточной Индии, аккредитованная JCI. По результатам опроса The Week–Hansa Research больница 12 лет подряд признавалась частной больницей №1 Восточной и Северо-Восточной Индии, а в 2019 году получила премию Global Health and Travel Awards как лучшая многопрофильная больница Восточной Индии.\n##specialities\nБольница располагает более чем 50 специальностями и 33 центрами передового опыта, включая кардиологическую помощь, онкологическую помощь, ортопедию, гастроэнтерологию, неврологию, трансплантологию, роботизированную хирургию и неотложную помощь. Провела первую в Восточной Индии одновременную трансплантацию сердца, печени и почки и внедрила в регионе полностью роботизированную трансплантацию почки; группа Apollo провела более 10 000 трансплантаций почек. Также является надёжным именем для трансплантаций костного мозга иностранным пациентам.\n##technology\nБольница обслуживает более 1600 амбулаторных визитов ежедневно и располагает трансплантологическими центрами, оснащёнными для операций с живым и трупным донором.\n##international\nБолее 10 000 иностранных пациентов в год, многие из Бангладеш, получают лечение в Apollo Kolkata, где работает отдельная команда по обслуживанию иностранных пациентов. Расположена в районе Kankurgachi, в Калькутте.",
	'amri-hospitals-dhakuria':
		"##history\nAMRI Hospitals, Dhakuria, начиналась в 1996 году как государственно-частное партнёрство с правительством Западной Бенгалии, сначала как амбулаторное учреждение, выросшее до больницы на 150 коек в 1997 году, а позже расширившееся до учреждения на несколько сотен коек. Manipal Hospitals приобрела контрольный пакет в группе AMRI в 2023 году, и больница в Dhakuria теперь называется Manipal Hospital Dhakuria (ранее AMRI); Manipal присутствует в Salt Lake, Dhakuria, Mukundapur и Broadway в Калькутте. Под брендом AMRI была названа лучшей частной больницей Восточной Индии на ABP News Healthcare Leadership Awards в 2020 и 2021 годах.\n##specialities\nБольница известна кардиологией, эндопротезированием суставов, травматологической помощью, ЭКО, челюстно-лицевой хирургией и эстетической и пластической хирургией. Служба неотложной и интенсивной помощи является центром передового опыта. В 2024 году получила награды на Economic Times Healthcare Awards за вклад в неотложную помощь и превосходство в неврологии и лечении инсульта, а также была отмечена правительством Бангладеш за услуги, оказываемые бангладешским пациентам.\n##technology\nПродвинутая ядерная визуализация включает ПЭТ-КТ и ОФЭКТ-КТ, а лучевая терапия включает IMRT и VMAT. Больница аккредитована NABH. Находится на Gariahat Road, Dhakuria, в южной части Калькутты.\n##international\nManipal Hospitals предлагает специализированные услуги для иностранных пациентов, включая медицинские заключения, планирование лечения, помощь в поездке и персонализированную поддержку.",
	'fortis-hospital-anandapur':
		"##history\nБольница Fortis Hospital, Anandapur, в Калькутте основана в 2011 году и занимает около семи акров вдоль Eastern Metropolitan Bypass. Это 10-этажное здание примерно на 300 коек, из которых около 240 действуют. Среди достижений — первая в Восточной Индии индивидуально изготовленная замена коленного сустава (2011), первая в Восточной Индии краниотомия в сознании (2012), запуск первой в Индии Heart Team (2012) и детская трансплантация почки ребёнку весом менее 12 кг (2014). Получила титул Times Bengal Icons 2023 как лучшее учреждение травматологической помощи города и награды на CAHOCON 2024.\n##specialities\nБольница специализируется на кардиологии и кардиохирургии, урологии, нефрологии, неврологии, ортопедии, лечении заболеваний пищеварения, пульмонологии, охране здоровья матери и ребёнка, неотложной помощи и интенсивной терапии. Также располагает специализированными клиниками по лёгочной гипертензии, неинвазивной вентиляции и аллергии, предлагает онкологию, челюстно-лицевую хирургию, стоматологию, психиатрию, диабетологию, дерматологию и ЛОР. Кардиологический центр располагает четырьмя катетеризационными лабораториями, одной кардиохирургической операционной, реанимацией на 14 коек и палатой интенсивного наблюдения на 20 коек.\n##technology\nБольница имеет аккредитацию NABH и сертификацию NABL.\n##international\nВходя в состав Fortis Healthcare, больница поддерживает иностранных пациентов через международные службы группы. Расположена в Anandapur, на EM Bypass, удобно для деловых районов и аэропорта.",
	'medica-superspecialty-hospital':
		"##history\nMedica Superspecialty Hospital в Mukundapur запущена в 2010 году и входит в группу Medica, описываемую как крупнейшую сеть больниц Восточной Индии. Это больница третичного уровня на несколько сотен коек, с 18 отделениями и восемью центрами передового опыта, по адресу 127 Eastern Metropolitan Bypass. В феврале 2022 года установила робота da Vinci четвёртого поколения, став первым официальным учебным центром роботизированной хирургии в Восточной Индии. Также является первой больницей Восточной Индии с сертифицированной «зелёной» операционной, в 2023 году получила Times Bengal Award.\n##specialities\nБольница охватывает анестезиологию, кардиологию, кардиохирургию, интенсивную терапию, дерматологию, стоматологию, неотложную медицину, эндокринологию, ЛОР, гастроэнтерологию, общую и ЖКТ-хирургию, гематологию, заболевания печени, нефрологию, неврологию, нейрохирургию, нейротологию, ядерную медицину, ортопедию, акушерство и гинекологию, онкологию, детскую хирургию, пластическую и реконструктивную хирургию, реабилитацию, психиатрию, рентгенологию, пульмонологию, ревматологию, роботизированную хирургию, трансфузионную медицину и урологию.\n##technology\nMedica располагает одним из самых продвинутых отделений интенсивной терапии региона, лабораторией, аккредитованной NABL, с молекулярной лабораторией, и визуализационными услугами, соответствующими международным стандартам. Диализный центр аккредитован в 2020 году и получил награду за лучший поставщик диализных услуг. Больница аккредитована NABH и NABL.\n##international\nMedica предлагает услуги для иностранных пациентов и является известным направлением для пациентов из соседних стран.",
	'zydus-hospitals':
		"##history\nZydus Hospitals в Ахмадабаде — инициатива Zydus Group, открытая в 2015 году на S. G. Highway рядом с Sola Bridge. Это больница узкой специализации на 550 коек, занимающая 16 этажей и два подземных этажа, аккредитована NABH и NABL. Была признана лучшей больницей Ахмадабада по опросу The Week–Marg четыре года подряд и стала 18-й больницей Гуджарата, получившей награду Global Green-OT. Больница привлекла к работе медицинских специалистов, обученных в США и Европе.\n##specialities\nZydus — центр неврологии, гастроэнтерологии, урологии, гинекологии, онкологии, хирургии позвоночника, косметической и пластической хирургии, нефрологии и ЛОР, с центрами передового опыта в ЭКО, эндопротезировании суставов, онкологической помощи, неврологии, кардиохирургии, трансплантации почек, трансплантации печени, нейрохирургии и пластической хирургии. Программу трансплантации печени поддерживает мультидисциплинарная команда из более чем 20 специалистов, а в центрах в Ахмадабаде и Вадодаре проведено более 430 трансплантаций почек, более 295 — печени и более 220 — костного мозга.\n##technology\nБольница сочетает современные операционные, продвинутую визуализацию и большую вместимость интенсивной терапии с практиками экологичного строительства.\n##international\nАхмадабад стал ключевым направлением в Западной Индии, и Zydus привлекает всё большую долю иностранных пациентов; её врачи также проводят медицинские кампании в странах Африки и Узбекистане.",
	'cims-hospital':
		"##history\nCIMS Hospital, ныне Marengo Asia CIMS Hospital, открылась в 2010 году рядом со Science City Road, в Sola (Ахмадабад), входит в группу Marengo Asia Hospitals. Это экологичная многопрофильная больница узкой специализации, аккредитованная NABH, NABL и JCI. В октябре 2023 года команда под руководством д-ра Dhiren Shah провела то, что представляется как первая в Азии трансплантация сердца без переливания крови, с использованием целенаправленного протокола контроля кровотечения; пациентка была выписана через девять дней вместо обычных 21–24.\n##specialities\nБольница предлагает онкологическую помощь, кардиологию, гастроэнтерологию, трансплантацию печени и желчевыводящих путей, ортопедию и эндопротезирование суставов, нефрологию, неврологию, трансплантацию костного мозга, бариатрическую хирургию, клиническую психологию, ревматологию, лечение диабетической стопы, стоматологию и дерматологию. Д-р Dhiren Shah, директор программы трансплантации сердца и первый хирург-трансплантолог сердца в Гуджарате, имеет на счету более 16 000 операций коронарного шунтирования и около 50 трансплантаций сердца, был первым в Индии, выполнившим трансаортальный TAVR и гибридное шунтирование. В больнице работает отдельный трансплантологический центр для сердца, печени, почек, лёгких и детской трансплантации костного мозга.\n##technology\nБольница описывается как учреждение на 300–500 коек, напротив Shukan Mall, с продвинутыми отделениями интенсивной терапии и операционными.\n##international\nБольница лечит пациентов из Индии и из-за рубежа.",
	'sterling-hospital':
		"##history\nSterling Hospitals в Gurukul, Memnagar (Ахмадабад), основана в 2001 году как больница третичного уровня и выросла в сеть больниц по всему Гуджарату. В 2009 году стала первой в Гуджарате больницей, полностью аккредитованной NABH, а её лаборатории первыми в штате получили аккредитацию NABL. Три года подряд (2007–2009) была признана лучшей больницей по версии IMRB и The Week.\n##specialities\nSterling предоставляет кардиологию, онкологию (хирургическую, медицинскую и лучевую), интенсивную терапию и пульмонологию, гастроэнтерологию и хирургию ЖКТ, неврологию и хирургию позвоночника, нефрологию и урологию, ортопедию и эндопротезирование суставов, акушерство и гинекологию, гематологию, травматологическую помощь, бариатрическую хирургию, ЛОР и анестезиологию. Провела первую трансплантацию печени в регионе, внедрила диализ CRRT и создала первое в Гуджарате отделение костного мозга и крупнейший в штате диализный центр. Признана ведущим кардиологическим центром Ахмадабада.\n##technology\nБольница располагает около 300 коек. Детские и неонатальные отделения интенсивной терапии оснащены мультипараметрическим мониторингом, аппаратами ИВЛ и ЭКМО, с высоким соотношением медсестёр к пациентам.\n##international\nSterling сообщает о лечении более 20 000 иностранных пациентов ежегодно из более чем 130 стран через единую службу для иностранных пациентов, координирующую больницу, врачей и пациентов.",
	'shalby-hospitals':
		"##history\nShalby Hospitals начиналась в Ахмадабаде в 1994 году как центр эндопротезирования суставов, созданный д-ром Vikram I. Shah, и за примерно 30 лет стала одной из самых быстрорастущих сетей многопрофильных больниц третичного уровня в западной, центральной и северной Индии. Флагманская больница в Ахмадабаде, Shalby Multispeciality Hospital, находится на S. G. Highway рядом с Ramdev Nagar, Satellite, основана в 2007 году. Д-р Shah является председателем Shalby и руководителем программы эндопротезирования суставов с 1993 года, в 2003 году получил Dr. B. C. Roy International Award. В 2025 году группа получила Hurun India Healthcare Transformation and Medical Excellence Award и награду за лучшую больницу для медицинского туризма в Гуджарате.\n##specialities\nShalby всемирно известна благодаря эндопротезированию суставов, проведено более 150 000 операций по замене суставов. Д-р Shah и его команда проводят более 800 первичных операций по замене суставов в месяц, а его техника ZERO сократила длительность операции по замене коленного сустава примерно с 80 минут до 10–12 минут. Группа также получила Rajiv Gandhi National Quality Award и награды FICCI.\n##technology\nБольница на SG Highway аккредитована NABH и NABL, располагает около 200 коек.\n##international\nShalby располагает специальным отделом для иностранных пациентов, предлагающим видеоконсультации, помощь в поездке и с визой, поддержку с проживанием, а также бесплатную встречу и проводы в аэропорту.",
	'dr-agarwal-s-eye-hospital':
		"##history\nDr. Agarwal's Eye Hospital основана в 1957 году в Ченнаи Padma Bhushan д-ром Jaiveer Agarwal и д-ром Tahira Agarwal. Д-р Jaiveer Agarwal получил Padma Bhushan в марте 2006 года. За десятилетия больница выросла в одну из крупнейших сетей офтальмологической помощи Индии, с центрами в 14 штатах и четырёх союзных территориях, а также в нескольких странах за рубежом, особенно в Африке. Точное число центров варьируется в зависимости от источника и меняется со временем, поэтому пациентам стоит уточнять актуальный список адресов в Дели-NCR при планировании поездки.\n##specialities\nБольница предоставляет комплексную офтальмологическую помощь, включая хирургию катаракты с использованием таких методов, как факоэмульсификация и ассистирование фемтосекундным лазером, LASIK и другую рефракционную хирургию, лечение сетчатки при таких состояниях, как диабетическая ретинопатия и отслойка сетчатки, глаукому, роговицу и детскую офтальмологию. Группа также связана с известными офтальмохирургами и исследователями, включая д-ра Amar Agarwal, известного своими инновациями в хирургии катаракты.\n##technology\nБольшинство офтальмологических процедур выполняются в режиме дневного стационара, что удобно для иностранных гостей. В Дели-NCR работает несколько центров Dr. Agarwal's.\n##international\nПоскольку многие офтальмологические процедуры требуют лишь короткого пребывания, пациенты часто могут совместить лечение с поездкой по региону.",
	'laimaa-fertility-ivf-surrogacy-clinic':
		"##history\nLaimaa Fertility основана в 2022 году командой опытных эмбриологов и врачей, расположена по адресу E-580, Greater Kailash Part II, Нью-Дели. Возникла под руководством эмбриолога Pooja Agarwal, д-ра Akanksha Chauhan и д-ра Mamta Chahar, при участии д-ра Vineet Malhotra, сочетая медицинскую и лабораторную экспертизу. Эмбриолог Pooja Agarwal начала карьеру в Fortis Ridge IVF Centre и руководила эмбриологическими лабораториями нескольких учреждений, включая Гуруграм и Нойду, является сертифицированным эмбриологом по биопсии эмбрионов.\n##specialities\nКлиника предлагает ЭКО, ИКСИ, ВМИ, заморозку яйцеклеток и эмбрионов, донорство яйцеклеток, индивидуальные схемы медикаментозной терапии, малоинвазивные хирургические процедуры при бесплодии и гормональную терапию. Известна работой со сложными случаями, такими как низкий уровень АМГ и тяжёлое мужское бесплодие, а её эмбриологическая команда выполняет TESA-ИКСИ, ПИКСИ, перенос бластоцисты и заморозку яйцеклеток и эмбрионов. Пациенты часто отмечают доброту, знания и доступность д-ра Akanksha Chauhan.\n##technology\nКлиника использует продвинутые репродуктивные технологии, делая упор на персонализированную заботу и этичную практику. Будучи более молодой клиникой, работает как целевой центр репродуктивной медицины с собственной эмбриологической лабораторией.\n##international\nКлиника предлагает консультации на английском и хинди. Greater Kailash Part II — хорошо обеспеченный район South Delhi с отелями и доступом к метро.",
	'gaudium-ivf':
		"##history\nGaudium IVF and Women Health основана в 2009 году д-ром Manika Khanna, всемирно признанным специалистом по бесплодию и лапароскопическим хирургом с более чем 20-летним опытом лечения бесплодия. В 2008 году получила Delhi Ratan Award из рук тогдашнего президента Индии, была удостоена наград, включая Rajiv Gandhi Excellence Award и Women Achievers' Award. Сегодня Gaudium насчитывает около 36 центров в шести штатах Индии и центры в других странах, сообщает о здоровых детях Gaudium более чем в 30 странах.\n##specialities\nЦентр предоставляет ЭКО, заморозку яйцеклеток и эмбрионов, известен лечением повторных неудач ЭКО, мужского бесплодия, эндометриоза и беременностей высокого риска. Д-р Khanna сообщает о более чем 10 000 проведённых процедурах ЭКО, а клиники группы описываются как учреждения узкой специализации с мультидисциплинарной помощью и опытными эмбриологами.\n##technology\nЭмбриологическая экосистема Gaudium использует инструменты на основе ИИ, включая SiD для оценки сперматозоидов и ERICA для оценки эмбрионов, в основе фреймворка Signature Lab, сочетающего продвинутую эмбриологию с международными стандартами качества. Клиника в Дели находится по адресу M-1, первый этаж, South Extension Part 2.\n##international\nGaudium лечила пары из более чем 30 стран. South Extension — оживлённый торговый район South Delhi с хорошей связью с метро.",
	'pristyn-care-ferticity-super-speciality-ivf-hospital':
		"##history\nPristyn Care Ferticity Super Speciality & IVF Hospital расположена по адресу 12, Navjeevan Vihar, Geetanjali Enclave, Malviya Nagar, Нью-Дели, сообщает о помощи более чем 40 000 семьям по всему миру. Её соучредитель и директор, д-р Ila Gupta, имеет более 29 лет опыта в лечении бесплодия и вспомогательных репродуктивных технологиях, провела более 5500 сложных случаев и в 2023 году получила Dr. APJ Abdul Kalam Health Award. Клиника внесена в реестр клиник ВРТ ICMR.\n##specialities\nБольница рассчитана на пары, ищущие ЭКО, ВМИ, ИКСИ, заморозку яйцеклеток и эмбрионов и донорские программы. Занимается СПКЯ, непроходимостью труб, низким овариальным резервом, мужским бесплодием, эндометриозом и повторными потерями беременности, предлагает индукцию овуляции и детальную гормональную и репродуктивную диагностику. Д-р Gupta сообщает о показателях успеха до 78% с использованием таких методов, как терапия обогащённой тромбоцитами плазмой и генетический скрининг, хотя результаты варьируются у разных пациентов.\n##technology\nВсе специалисты по фертильности зарегистрированы в медицинском совете, клиника работает как учреждение узкой специализации и ЭКО с операционными, эмбриологической лабораторией и психологической поддержкой. Работает с понедельника по субботу.\n##international\nКлиника принимала иностранные пары, включая пациентов, приезжавших из США для ЭКО с д-ром Gupta. Malviya Nagar находится рядом со станцией метро Malviya Nagar в South Delhi.",
	'nova-ivf-fertility-centre-rajouri-garden':
		"##history\nЦентр Nova IVF Fertility в Rajouri Garden — одна из клиник группы в Дели, по адресу GN-14, Shivaji Enclave, Sector G, Mehta Chowk, рядом со станцией метро Rajouri Garden. Nova IVF Fertility основана в 2011 году, группа получила премию Best IVF Chain in India на ET Healthworld National Fertility Awards в 2021 году и премию IVF/Fertility Champion of the Year в 2025 году. Группа сообщает о более чем 85 000–100 000 живорождённых детей после ЭКО по всей сети.\n##specialities\nКлиника предлагает ВМИ, ЭКО, ИКСИ и отбор сперматозоидов методом MACS, заморозку яйцеклеток, донорские программы и продвинутую диагностику, лечит мужское бесплодие, бесплодие неясного генеза, низкий овариальный резерв, СПКЯ, эндометриоз и трубное бесплодие. Д-р Aswati Nair — специалист по ЭКО: окончила MBBS в Мумбаи и MD по акушерству и гинекологии, затем прошла FNB по репродуктивной медицине, имеет более 17 лет опыта. Получила премию за лучшую работу в отделении Кералы ISAR за исследование эмбрионального клея при повторных неудачах имплантации. Д-р Meenakshi Banerjee, гинеколог с более чем 20-летним опытом, также практикует здесь.\n##technology\nКак и другие клиники Nova IVF в Дели NCR, располагает продвинутой эмбриологической лабораторией, современной операционной и комфортной зоной восстановления, следуя международным протоколам. Клиника работает с понедельника по субботу.\n##international\nRajouri Garden хорошо связан на метро с центром Дели и линией до аэропорта.",
	'elixir-fertility-centre':
		"##history\nElixir Fertility Centre основан в 2014 году, это клиника ЭКО и лечения бесплодия в северном Дели, по адресу Vardhman Royal Plaza, Plot 5, LSC Gujranwala Town-1. Стремится сочетать опытных специалистов по бесплодию с продвинутыми технологиями для повышения показателей успеха, а её специалисты по ЭКО и эмбриологи обучались в ведущих центрах Великобритании, Германии, Сингапура и Индии.\n##specialities\nКлиника предлагает ЭКО, ИКСИ, ВМИ, анализ спермы и генетический скрининг. В команду входят д-р Puneet Kochhar, специалист по ЭКО, ранее работавший в Bourn Hall Clinic в Кембридже, Великобритания, и преподававший в Lady Hardinge Medical College в Дели; д-р Pranay Ghosh, директор и консультант по фертильности, обучавшийся в таких центрах, как NURTURE в Ноттингеме, NUH CREST в Сингапуре и Centre of Reproductive Medicine в Киле, с отличием окончивший магистратуру в Великобритании; д-р Rajiv Singla, репродуктивный эндокринолог; и д-р Teita Ghosh, клинический генетик и репродуктивный иммунолог.\n##technology\nКлиника располагает диагностической лабораторией, УЗИ, службой неотложной помощи и парковкой, работает с понедельника по субботу примерно с 9 до 18 часов. Сообщает о показателях успеха ЭКО в диапазоне 65–75%, которые будут варьироваться в зависимости от индивидуальных обстоятельств.\n##international\nGujranwala Town в северном Дели находится рядом с Model Town и Kamla Nagar, добраться можно на метро из центра Дели.",
	'femmenest-fertility-ivf-centre':
		"##history\nFemmenest — премиальный центр женского здоровья в восточном Дели, предоставляющий услуги ЭКО, лечения бесплодия и гинекологии, по адресу C-52 UGF, Anand Vihar, напротив Pushpanjali Medical Centre. Центр возглавляет д-р Sowjanya Aggarwal, специалист по ЭКО и гинекологический лапароскопический и роботизированный хирург с более чем 20-летним клиническим опытом. Она окончила MS по акушерству и гинекологии в Sri Ramachandra University, Ченнаи, затем прошла стажировку по гинекологической хирургии минимального доступа и репродуктивной медицине в Кочи, в 2012 году получила Dr. Jagdishwari Mishra Oration Award.\n##specialities\nЦентр предоставляет ЭКО, ВМИ и ИКСИ, персонализированную поддержку пар, комплексную помощь при бесплодии от диагностики до гормональной терапии, а также продвинутую гинекологическую помощь при СПКЯ, гормональных нарушениях, вопросах фертильности и регулярных обследованиях женского здоровья, наряду с фетальной медициной. Здесь работает команда старших врачей, клинических эмбриологов, вспомогательного персонала и специализированных медсестёр.\n##technology\nЦентр оснащён современным оборудованием для комплексной заботы о здоровье женщины. Обычно работает с понедельника по субботу с 9 до 20 часов и по воскресеньям в первой половине дня, получает высокие оценки от пациентов.\n##international\nAnand Vihar хорошо связан метро и железнодорожным и автовокзалом Anand Vihar, что удобно для путешественников, прибывающих из других городов.",
	'india-ivf-clinic':
		"##history\nIndia IVF Clinic в Vasant Vihar — клиника лечения бесплодия сети Fortis. Ведёт консультативный приём в Fortis Flt. Lt. Rajan Dhall Hospital в Vasant Kunj, находится по адресу 35, Second Floor, Community Centre, Basant Lok, Vasant Vihar. Работает в сфере здравоохранения около 12 лет, получает высокие оценки от пациентов.\n##specialities\nД-р Richika Sahay возглавляет команду по лечению бесплодия. Имеет более 20 лет опыта в качестве специалиста по фертильности и гинекологического лапароскопического хирурга, является сертифицированным репродуктивным эндокринологом и субспециалистом по бесплодию (ЭКО-ИКСИ), окончила медицинский вуз с золотой медалью и в 2018 году получила премию лучшего молодого специалиста ЭКО. Сферы её экспертизы включают ЭКО и ИКСИ, заморозку яйцеклеток и эмбрионов, индукцию овуляции, ВМИ, предимплантационное генетическое тестирование и скрининг, а также ведение случаев зачатия и выкидышей. Придерживается целостного подхода, уделяя внимание питанию, образу жизни и окружающей среде.\n##technology\nКлиника доступна для инвалидных колясок, имеет парковку. Пациенты описывают персонал как дружелюбный, внимательный и поддерживающий, упоминают успешные беременности и роды.\n##international\nПоскольку команда также работает в Fortis Vasant Kunj, рядом с международным аэропортом, иностранные пары могут совместить консультации по фертильности с хорошо оснащённой многопрофильной больницей.",
	'spruce-dental':
		"##history\nSpruce Dental в Jasola Vihar (South Delhi) входит в состав группы клиник Spruce Dental под руководством имплантолога и ортодонта д-ра Javed Rizwan, сертифицирована ISO 9001:2015. Находится по адресу 122, Pocket 2, Jasola, рядом со школой DAV, получает хорошие оценки пациентов. Д-р Rizwan имеет степени BDS и MDS, прошёл магистратуру по стратегической имплантологии под руководством пионера кортикобазальной имплантологии в Мюнхене, Германия. На его счету более 15 000 имплантатов и более 500 случаев немедленной имплантации всей челюсти.\n##specialities\nКлиника предоставляет безболезненное лечение корневых каналов для спасения повреждённых зубов, зубные имплантаты для полной реконструкции при отсутствии зубов, единичные имплантаты, профессиональное отбеливание, продвинутые варианты ортодонтии и преображение улыбки с помощью эстетической стоматологии. Группа ведёт программы клинической ординатуры по общей стоматологии и имплантологии.\n##technology\nЦифровая визуализация даёт чёткое представление о зубах и дёснах для лучшего планирования лечения, клиника стремится обеспечивать этичную, ориентированную на пациента стоматологическую помощь в комфортной обстановке.\n##international\nJasola Vihar расположен рядом с Indraprastha Apollo Hospital и станциями метро Jasola в South Delhi. Работа с зубными имплантатами и дизайн улыбки часто планируются за небольшое число визитов.",
	'zemya-ivf-fertility-clinics':
		"##history\nZemya IVF & Fertility Clinics — центр лечения бесплодия по адресу C-10, Green Park Extension, Нью-Дели, описывается как один из ведущих центров ЭКО в Дели NCR. Предлагает чуткую, ориентированную на пациента помощь, сообщает о помощи более чем 50 000 парам. В команду входят специалисты по ЭКО с международной подготовкой и эмбриологи, сертифицированные ESHRE, включая старшего эмбриолога и руководителя эмбриологической лаборатории с более чем 15-летним опытом клинической эмбриологии и вспомогательных репродуктивных технологий.\n##specialities\nZemya предоставляет ЭКО, ИКСИ и ВМИ, помощь при мужском бесплодии, заморозку яйцеклеток и сохранение фертильности под одной крышей, с индивидуальными планами лечения. Страницы лечения подробно освещают ЭКО, ИКСИ и мужское бесплодие.\n##technology\nОснащение включает просторные залы ожидания, приватные и люксовые палаты восстановления, модульные операционные, современную ЭКО-лабораторию, продвинутую андрологическую лабораторию для анализа мужской фертильности, собственную аптеку, лабораторию патологии, зону для иностранных пациентов, кабинет консультирования, конференц-зал и услуги видеоконсультаций.\n##international\nGreen Park — хорошо связанный район South Delhi с доступом к метро, отелями и ресторанами, а в клинике есть зона для иностранных пациентов.",
	'kokilaben-dhirubhai-ambani-hospital':
		"##history\nБольница Kokilaben Dhirubhai Ambani Hospital на Rao Saheb Achutrao Patwardhan Marg в Andheri West (Мумбаи) начала работу в начале 2009 года как многопрофильная больница на 750 коек. Обслуживает Мумбаи, соседние регионы и иностранных пациентов, аккредитована JCI, NABH и CAP. В 2025 году была названа Best Hospital – National в шести категориях (многопрофильная помощь, онкология, роботизированная хирургия, неврология, ортопедия и реабилитация) на Financial Express Healthcare Summit and Awards, получила NABH Digital Health Excellence Award.\n##specialities\nБольница сообщает о более чем 21 000 сложных онкологических операциях, более чем 280 трансплантациях печени и более чем 3600 роботизированных операциях, выполненных командой из более чем 400 врачей. Её Centre for Robotic Surgery, созданный в 2012 году, описывается как самый быстрый в мире, достигший 1000 роботизированных операций за 48 месяцев с момента запуска. Онкология, неврология, ортопедия, кардиология, трансплантология и реабилитация — среди основных сильных сторон.\n##technology\nБольница располагает около 180 койками интенсивной терапии, стала местом нескольких «первых» достижений, включая первый в Азии трёхкабинетный комплекс интраоперационной МРТ (IMRIS), первую в Азии систему радиохирургии EDGE от Varian и первый в Индии кабинет хирургии позвоночника с O-дугой. Использует da Vinci Xi и первую в Индии роботизированную хирургическую систему Toumai, предлагающую 3D HD-визуализацию и возможность телехирургии.\n##international\nKokilaben известна заботой об иностранных пациентах, консьерж-услугами и помощью по всем аспектам медицинской поездки. Andheri West находится рядом с метро и международным аэропортом Мумбаи.",
	'p-d-hinduja-hospital':
		"##history\nP. D. Hinduja Hospital основана в 1951 году Parmanand Deepchand Hinduja в сотрудничестве с Massachusetts General Hospital, главной учебной больницей Harvard Medical School, переехала в здание своего East Wing на территории в Mahim в 1963 году, превратившись из скромного амбулаторного учреждения в полноценную больницу. Находится на Veer Savarkar Marg, рядом с Shivaji Park. Стала первой больницей Индии, получившей Green and Clean Hospital Platinum Certificate от Bureau Veritas, завоевала награды, включая IMC Ramkrishna Bajaj National Award за качество здравоохранения.\n##specialities\nБольница предоставляет услуги более чем по 45 специальностям, за исключением акушерства, с 53 койками интенсивной терапии, 19 отделениями дневного стационара, 170 консультантами и более чем 800 медсестрами и другим персоналом, а также центром скрининга здоровья. Стала первой частной больницей Мумбаи, выполнившей трансплантацию почки от трупного донора и трансплантацию периферических стволовых клеток крови, и первой в Индии, выполнившей краниотомию в сознании для хирургии эпилепсии. Кардиология, онкология, неврология и ортопедия — среди основных сильных сторон.\n##technology\nБольница ведёт курсы DNB по 26 специальностям, программы магистратуры и докторантуры, школу медсестёр и курсы смежных медицинских специальностей, сотрудничает с такими учреждениями, как Hôpitaux Universitaires de Genève, Stanford University и Henry Ford Health. Аккредитована NABH.\n##international\nБольница располагает отдельным отделом услуг для иностранных пациентов, помогающим планировать и координировать лечение. Mahim хорошо связан железной дорогой и автомагистралями с центром Мумбаи и аэропортом.",
	'fortis-hospital-mulund':
		"##history\nБольница Fortis Hospital, Mulund, открылась в 2002 году, это многопрофильная больница четвертичного уровня на 400 коек на Mulund–Goregaon Link Road. Её описывают как первую больницу Индии и Южной Азии, получившую аккредитацию JCI, единственную в Западной Индии с семью аккредитациями JCI подряд. Стала первой в стране, получившей аккредитацию NABH для служб неотложной помощи, и первой в Индии, запустившей электронное отделение интенсивной терапии. Больница получила более 250 наград за качество здравоохранения.\n##specialities\nFortis Mulund располагает крупнейшим в штате Махараштра центром многоорганной трансплантации, охватывающим почки, печень, сердце и костный мозг. Была первой в Западной Индии, выполнившей более 100 трансплантаций сердца всего за четыре года, а в 2024 году провела 100-ю трансплантацию костного мозга. Программа неврологии с продвинутой нейровизуализацией и отделениями нейрореанимации считается одной из лучших в Индии, также предлагаются кардиология, онкология, нефрология, урология, ортопедия, гастроэнтерология, неотложная и интенсивная помощь и родовспоможение.\n##technology\nБольница располагает 108 койками интенсивной терапии, шестью специализированными отделениями трансплантации костного мозга и травматологическим центром 1 уровня. Онкология использует линейный ускоритель Versa HD, больница входит в число немногих в стране, обладающих этой платформой лучевой терапии.\n##international\nFortis Mulund управляет круглосуточным International Patient Unit, поддерживающим пациентов и семьи на протяжении всего медицинского процесса. Находится в восточных пригородах Мумбаи, рядом с железнодорожной станцией Mulund.",
	'jaslok-hospital':
		"##history\nJaslok Hospital & Research Centre на Dr. G. Deshmukh Marg, на Peddar Road, была основана филантропом Seth Lokoomal Chanrai и хирургом Shantilal Jamnadas Mehta, открыта 6 июля 1973 года премьер-министром Indira Gandhi. Это одна из старейших в Индии многопрофильных больниц третичного уровня при благотворительном фонде, отметившая 50 лет работы Navbharat Healthcare Award в 2022 году.\n##specialities\nБольница располагает около 50 специальностями и почти 20 специализированными клиниками, с более чем 350 койками, включая более 75 коек интенсивной терапии. В 1974 году здесь провели первую трансплантацию почки в частной больнице Индии, запустили первое частное отделение урологии в Индии, в 1998 году провели первую частную трансплантацию печени в Мумбаи и первую детскую трансплантацию печени в Западной Индии. Внедрили первую в Индии трёхдетекторную гамма-камеру и первую твердотельную кардиологическую камеру, стали первыми в Мумбаи, внедрившими 2D-эхокардиографию, электрофизиологию и стенты с лекарственным покрытием. В репродуктивной медицине сообщают о первом в мире переносе с кумулюс-ассистированием в ЭКО, в 2019 году получили премию Best IVF Clinic на ET Healthcare Fertility Awards.\n##technology\nБольница аккредитована NABH (5-е издание), NABL, имеет сертификаты ISO 9001, 14001 и 45001, а также аккредитацию качества сестринского ухода и комитета по этике NABH.\n##international\nJaslok предоставляет поддержку иностранным пациентам, включая консультацию до прибытия и планирование расходов с помощью телеконсультаций и подробных планов лечения, а также помощь с визой и поездкой. Находится в южном Мумбаи, рядом с Mahalaxmi.",
	'nanavati-max-super-speciality-hospital':
		"##history\nБольница Nanavati Max Super Speciality Hospital в Vile Parle была открыта в ноябре 1950 года первым премьер-министром Индии Jawaharlal Nehru, благословлена Mahatma Gandhi, начала приём пациентов в 1951 году. Более 70 лет служит опорой здравоохранения Мумбаи, сегодня входит в состав Max Healthcare. Располагает 350 койками, более чем 350 консультантами, более чем 100 врачами-ординаторами, около 475 медсёстрами и около 1500 сотрудниками.\n##specialities\nБольница располагает 55 профильными отделениями и центрами передового опыта в кардиологии, онкологии, нефрологии, ортопедии, хирургии позвоночника, неврологии, бариатрии и хирургической гастроэнтерологии. Также предлагает физиотерапию, дерматологию, пластическую хирургию, детскую неврологию, пульмонологию, малоинвазивную хирургию позвоночника, трансплантацию костного мозга, акушерство и гинекологию, лечение заболеваний пищеварения и печени, общую и лапароскопическую хирургию, эндопротезирование суставов и неврологию. Запустила Centre for Robotic Surgery в 2019 году, а в 2018 году внедрила терапию апоморфиновой ручкой и помпой при болезни Паркинсона в сотрудничестве с King's College London.\n##technology\nВизуализационный центр занимает более 10 000 квадратных футов, оснащён широкотуннельной МРТ 3 Тесла и 64-срезовым ПЭТ-КТ с кардиологическими возможностями. Больница аккредитована NABH и NABL, получила награды, включая Best Hospital for Patient Safety (2021) и Hospital of the Year in Organ Transplant (2024).\n##international\nБольница располагает отдельным International Patient Desk, предлагающим бесплатную встречу и проводы в аэропорту, помощь с визой, координацию медицинской туристической страховки, переводчиков, обмен валюты и индивидуальное питание. Находится в Vile Parle West, рядом с внутренним и международным аэропортами Мумбаи.",
	'apollo-hospitals-greams-road':
		"##history\nApollo Hospitals, Greams Road, была запущена в 1983 году д-ром Prathap C. Reddy как первая в Индии профессионально управляемая частная больница на 150 коек, а как первая корпоративная больница страны сыграла важную роль в трансформации частного здравоохранения. Д-р Reddy был удостоен Padma Vibhushan и наград за жизненные достижения от трёх медиахолдингов. Сегодня больница располагает 550 койками, аккредитована JCI и NABH, широко считается одной из лучших больниц Индии для иностранных пациентов.\n##specialities\nБольница располагает более чем 12 центрами передового опыта, включая Apollo Heart Institute, Institute of Liver Sciences, Institute of Neurosciences, Institute of Colorectal Surgery и Institute of Robotic Surgery. Программа трансплантации охватывает печень, почки, сердце и лёгкие, с такими достижениями, как первая успешная трансплантация поджелудочной железы в Индии и первая в Азии комбинированная трансплантация сердца и печени en-bloc. Была первой в Индии, внедрившей коронарную ангиопластику, стереотаксическую лучевую терапию и радиохирургию опухолей мозга.\n##technology\nТехнологии включают роботизированную хирургическую систему da Vinci, ExcelsiusGPS для хирургии позвоночника, TrueBeam STx для лучевой терапии, первый в Индии CyberKnife и использование 64-срезового ПЭТ-КТ в Юго-Восточной Азии. Центр протонной терапии описывается как первый в Индии и самый продвинутый в Южной Азии.\n##international\nApollo Chennai была признана самой перспективной компанией в области международных медицинских услуг (MT India Healthcare Awards, 2023). Находится на Greams Lane, рядом с Greams Road, в центре Ченнаи, недалеко от отелей.",
	'miot-international':
		"##history\nMIOT International, Madras Institute of Orthopaedics and Traumatology, был основан Padmashri проф. д-ром P. V. A. Mohandas 12 февраля 1999 года как больница на 70 коек, специализирующаяся на ортопедии и травматологии. Д-р Mohandas провёл первую в Индии операцию по замене тазобедренного сустава и в 1992 году получил Padmashri за новаторскую работу в эндопротезировании суставов. Больница выросла в центр четвертичной помощи на 1000 коек в Manapakkam, с 63 специальностями и 21 операционной, принимая пациентов из более чем 130 стран.\n##specialities\nОтделение ортопедии и эндопротезирования суставов MIOT было признано первым в Индии по версии Outlook Health, здесь проведено более 40 000 операций по замене тазобедренного, коленного суставов и суставов верхних конечностей. Среди достижений — первая операция через замочную скважину, первая в Индии трансплантация почки при несовпадающих группах крови, первая в Индии гаплоидентичная трансплантация костного мозга и первая в Азиатско-Тихоокеанском регионе установка лучевой терапии TrueBeam STx. С 2012 года MIOT International Centre объединяет онкологию, лучевую онкологию, центр трансплантации печени и центр трансплантации костного мозга, наряду с кардиологией, нефрологией, нейрохирургией, пластической хирургией, педиатрией и акушерством.\n##technology\nБольница аккредитована NABH и NABL, получила награды, включая Times Healthcare Legends in Orthopaedics и Best Multi-Speciality Hospital in Chennai (2018), Radio City ICON Award (2019) и Times Healthcare Achievers Awards (2020).\n##international\nMIOT предоставляет письма-приглашения для визы, бесплатный трансфер из аэропорта и поддержку многоязычных переводчиков. Находится на Mount Poonamallee Road, недалеко от аэропорта Ченнаи.",
	'gleneagles-global-health-city':
		"##history\nGleneagles Global Health City в Perumbakkam (Ченнаи) входит в состав IHH Healthcare и является одной из крупнейших в Индии больниц многоорганной трансплантации и четвертичной помощи, на кампусе площадью 21 акр. Институт заболеваний печени и трансплантации, созданный в 2009 году проф. Mohamed Rela, провёл более 1500 трансплантаций печени и считается одной из крупнейших программ трансплантации печени в Индии. Проф. Rela провёл более 4000 трансплантаций печени и включён в Книгу рекордов Гиннесса за трансплантацию печени пятидневному младенцу.\n##specialities\nБольница располагает более чем 40 специальностями и получила международное признание в трансплантации органов, онкологии, гепатологии, неврологии и травматологической помощи. Проводит трансплантации печени, почек, сердца, лёгких и костного мозга, сообщает, что первой в Южной Индии выполнила пять трансплантаций органов за один день, первой в Индии провела перекрёстную трансплантацию печени у взрослых и трансплантацию с разделением печени, а также первой в Индии имплантировала искусственное лёгкое и провела трансплантацию матки. Программа трансплантации лёгких считается одной из лучших в Индии, трансплантации печени проводятся в сотрудничестве с King's College Hospital в Лондоне.\n##technology\nБольница сообщает о вместимости около 1000 коек, аккредитована NABH и NABL, имеет халяльный сертификат для питания.\n##international\nБольница стремится предлагать условия, соответствующие международным стандартам, по конкурентным ценам, особенно для многоорганной трансплантации. Perumbakkam находится в южной части Ченнаи, рядом с ИТ-коридором.",
	'fortis-malar-hospital':
		"##history\nБольница Fortis Malar Hospital в Adyar (Ченнаи) основана в 1992 году как Malar Hospital, в 2007 году вошла в состав Fortis Healthcare. Это многопрофильная больница третичного уровня на 180 коек, оказывающая помощь более чем по 40 специальностям. Известна своим Fortis Centre for Heart Failure and Transplant, описываемым как первый в Индии комплексный центр лечения сердечной недостаточности.\n##specialities\nКардиологическая программа больницы охватывает интервенционную, инвазивную, неинвазивную и детскую кардиологию, сердечно-сосудистую хирургию и трансплантацию сердца. Центр провёл более 50 трансплантаций сердца, долгосрочные имплантации LVAD и вено-артериальное ЭКМО-сопровождение при критической сердечной недостаточности; ему приписывают первые успешные в Индии имплантации Heartmate II LVAD и HVAD. Д-р K. R. Balakrishnan, директор по кардиологии, имеет более 30 лет опыта, провёл более 16 000 операций на сердце, получил FICCI Special Jury Award. Больница также предлагает неврологию, нейрохирургию, ортопедию, нефрологию, гинекологию, гастроэнтерологию, урологию, педиатрию и лечение диабета.\n##technology\nБольница аккредитована NABH. Цифры коечной ёмкости различаются в зависимости от источника, пациентам стоит уточнять актуальную вместимость при планировании.\n##international\nБольница лечит пациентов из-за рубежа; недавний случай — успешная трансплантация сердца 40-летнему гражданину Пакистана. Adyar — спокойный жилой район на юге Ченнаи.",
	'kauvery-hospital':
		"##history\nKauvery Hospital в Alwarpet, по адресу 81, TTK Road, — многопрофильная больница в центре Ченнаи, входящая в группу Kauvery, располагающую более чем 2000 коек в 10 локациях штатов Тамил-Наду и Карнатака. Больница описывается Newsweek как одна из 20 лучших больниц Индии, 25 лет создавала сеть хирургов с международной подготовкой. Её больницы в Alwarpet и Vadapalani имеют аккредитацию JCI, описываемую как единственная в Индии сеть с двойной аккредитацией JCI 8-го издания.\n##specialities\nKauvery располагает центрами передового опыта в кардиологии, неврологии, гастроэнтерологии, трансплантации органов, ортопедии и женском здоровье. Kauvery Heart Institute в Alwarpet сосредоточен на сложной ангиопластике, Impella, гибридном шунтировании и трансплантации сердца. Команда трансплантации сердца и лёгких, включающая хирургов-трансплантологов, кардиологов по сердечной недостаточности, пульмонологов-трансплантологов, торакальных анестезиологов, реаниматологов, перфузиологов и координаторов, в 2023 году была отмечена Tamil Nadu State Transplant Authority (TRANSTAN).\n##technology\nKauvery Institute of Robotic Surgery предлагает роботизированную хирургию da Vinci в онкологии, урологии, желудочно-кишечной, колоректальной и кардиохирургии, хирургии печени и трансплантации почек. Больница располагает около 300 коек в семиэтажном здании рядом с путепроводом Alwarpet, аккредитована NABH.\n##international\nМногих иностранных пациентов в Kauvery привлекает её высокоспециализированная медицинская команда. Alwarpet удобно расположен в центре Ченнаи, рядом с отелями и ресторанами.",
	'manipal-hospital-old-airport-road':
		"##history\nManipal Hospital, Old Airport Road, была открыта в Бангалоре в 1991 году как первая корпоративная больница города и стала флагманом сети Manipal Hospitals и краеугольным камнем Manipal Education and Medical Group. Была названа Best Multispeciality Hospital (Private) на The Week Health Summit 2025 и Best Multi-Speciality Hospital in Bengaluru на The Week Best Hospitals Awards 2024, в 2005 году получила Golden Peacock National Quality Award. Аккредитована NABH и JCI.\n##specialities\nБольница предлагает более 60 узких специализаций с центрами передового опыта в онкологии, кардиологии, неврологии, гастроэнтерологии, ортопедии и трансплантации органов. Является признанным центром многоорганных трансплантаций с комплексными программами по почкам, печени, поджелудочной железе, сердцу, лёгким и костному мозгу, известна ранним внедрением в Индии роботизированной трансплантации почек. Программа трансплантации более широкой сети — одна из крупнейших в стране.\n##technology\nБольница располагает около 600 коек или более, включая 144 койки интенсивной терапии, и 20 модульными операционными, а также продвинутой онкологической помощью и отделениями трансплантации органов.\n##international\nБольница обслуживает пациентов из более чем 80 стран, предлагая комплексную поддержку: консультацию до прибытия и планирование лечения с помощью телеконсультаций, помощь с визой и поездкой, включая письма-приглашения для медицинской визы, встречу и проводы в аэропорту, размещение, перевод и многоязычных переводчиков. Находится на HAL Old Airport Road.",
	'sakra-world-hospital':
		"##history\nБольница Sakra World Hospital в Бангалоре была запущена в феврале 2014 года, описывается как первая в Индии японская многопрофильная больница и первая больница Индии со 100%-ными прямыми иностранными инвестициями, принадлежащая и управляемая совместным предприятием Toyota Tsusho и Secom Hospitals из Японии, с участием Kirloskar на этапе запуска. Сочетает сильные стороны Индии и Японии, а протоколы сестринского ухода объединяют индийскую и японскую практику. Получила Award for Excellence in Healthcare от Indian Business Awards, национальное признание от министерства здравоохранения и благосостояния семьи, а также первую National Award for Laboratory Excellence от QCI. Также получила аккредитацию AACI, объявлено о строительстве второй больницы на 500 коек.\n##specialities\nБольница предлагает неврологию, кардиологию, ортопедию, акушерство и гинекологию, нефрологию, реабилитологию, педиатрию, хирургию позвоночника, рентгенологию, клиническую психологию, внутренние болезни, ЛОР, хирургию головы и шеи, онкологию, заболевания крови, пластическую хирургию, пульмонологию, ревматологию, эндокринологию, стоматологию, дерматологию, психиатрию, офтальмологию, интенсивную терапию, медицину боли и многое другое. Известна кардиологией, ортопедией, неврологией и трансплантацией органов. Sakra Institute of Rehabilitation Sciences считается крупнейшим реабилитационным центром Азии и первым с глобальной сертификацией качества.\n##technology\nБольница располагает 350 стационарными койками, визуализация включает МРТ, мультидетекторный КТ, УЗИ 3D и 4D, цифровой рентген, ортопантомографию и денситометрию костей.\n##international\nОтдельный отдел услуг для иностранных пациентов заботится о пациентах и сопровождающих, прибывающих из-за рубежа, с оформлением виз, трансферами из аэропорта, размещением, языковой интерпретацией и персонализированным управлением лечением. Больница находится на Outer Ring Road, рядом с Marathahalli и Bellandur.",
	'narayana-institute-of-cardiac-sciences':
		"##history\nNarayana Institute of Cardiac Sciences был введён в строй в 2000 году как часть NH Health City в Bommasandra (Бангалор) кардиохирургом д-ром Devi Shetty, основателем Narayana Health. Это флагманский кардиологический центр Narayana Health и одна из крупнейших кардиологических больниц мира, часть кампуса, описываемого как один из крупнейших в мире центров кардиологической помощи. Институт провёл более 100 000 кардиологических процедур, располагает командой из более чем 250 кардиологов и кардиологических специалистов. Аккредитован JCI и NABH.\n##specialities\nИнститут специализируется на кардиохирургии и трансплантации сердца, также предоставляет услуги электрофизиологии, имплантации устройств вспомогательного кровообращения левого желудочка (LVAD), транскатетерной имплантации аортального клапана (TAVI) и программу структурных заболеваний сердца. Ежедневно проводит более 40 кардиохирургических операций, включая около 16 детских операций на сердце.\n##technology\nУчреждение располагает около 20 кардиохирургическими операционными, включая две продвинутые роботизированные, и несколькими цифровыми катетеризационными лабораториями, включая гибридную лабораторию для интервенционных процедур и сложных операций на сердце. Имеет около 200 коек интенсивной терапии для послеоперационного ухода.\n##international\nИнститут находится примерно в 50 км от международного аэропорта Кемпеговда, удобен для пациентов, путешествующих из других регионов Индии и из-за рубежа. Расположен на Hosur Road, рядом с Electronic City.",
	'fortis-hospital-bannerghatta-road':
		"##history\nБольница Fortis Hospital, Bannerghatta Road, открылась в 2006 году, это флагманская многопрофильная больница Fortis Healthcare в Южной Индии, напротив IIM Bangalore. Аккредитована NABH (четыре раза) и JCI (пять раз), считается первой больницей Карнатаки, получившей аккредитацию JCI. Получала награды, включая награды AHPI, National Energy Conservation Award (2014), Asian Patient Safety Award и международную аккредитацию медицинского туризма за превосходство в уходе, входила в число лучших многопрофильных больниц Бангалора по версии The Week.\n##specialities\nБольница оказывает третичную помощь узкой специализации примерно по 40 медицинским направлениям, с центрами передового опыта в кардиологии и кардиохирургии, неврологии и нейрохирургии, онкологии, ортопедии, трансплантации органов, гастроэнтерологии, педиатрии и интенсивной терапии. Онкологическое отделение предлагает продвинутую лучевую терапию, химиотерапию, онкологические консилиумы и трансплантацию костного мозга, роботизированную онкологическую хирургию и HIFU при раке простаты, при поддержке ПЭТ-КТ, ПЭТ-МРТ, МРТ 3T и молекулярной диагностики. Кардиологическая программа включает ангиопластику, шунтирование, восстановление клапанов, электрофизиологию, гибридную кардиохирургию и трансплантации сердца и лёгких, а Fortis Institute of Robotic Surgery является центром передового опыта.\n##technology\nБольница располагает около 280 коек, более чем 150 врачами и 800 сотрудниками среднего медперсонала, с неотложной помощью, трансплантацией органов и профилактической помощью.\n##international\nFortis Bannerghatta Road предлагает услуги для иностранных пациентов с помощью в оформлении медицинской визы, переводчиками и консьерж-сервисом, сообщает о помощи пациентам из более чем 175 стран. Находится на Bannerghatta Road в южном Бангалоре.",
	'aster-cmi-hospital':
		"##history\nAster CMI Hospital в Hebbal (Бангалор) входит в состав Aster DM Healthcare, одной из крупнейших сетей здравоохранения Азии, работающей в девяти странах. Источники расходятся в отношении года открытия, поэтому её лучше описать как больницу 2010-х годов. Аккредитована NABH и NABL, располагает почти 500 койками — от первичной до четвертичной помощи. Стала первой больницей Бангалора, выбранной центром трансплантации почек штата Карнатака, и первой в Карнатаке, сертифицированной FPID (США) как центр передового опыта по первичным иммунодефицитам.\n##specialities\nAster CMI предлагает центры передового опыта в кардиологии, неврологии, гастроэнтерологии, комплексной помощи при заболеваниях печени, трансплантации органов, урологии и нефрологии, ортопедии, женском здоровье и здоровье детей и подростков, с более чем 38 специальностями под одной крышей. Программа трансплантации в общей сложности выполнила более 1000 трансплантаций почек, включая 54 роботизированные трансплантации почек на сегодняшний день с использованием хирургического робота da Vinci. Aster International Institute of Oncology предлагает протонную терапию, роботизированную хирургию, HIPEC и молекулярное профилирование опухолей.\n##technology\nБольница расположена в районе Hebbal, на дороге к аэропорту, её отделение урологии и нефрологии вошло в число лучших в Бангалоре по опросу о критической помощи Times of India.\n##international\nДля иностранных пациентов Aster CMI предоставляет отдельную координацию, трансферы из аэропорта, переводчиков на иностранные языки и помощь с визой. Hebbal находится на маршруте между центром Бангалора и международным аэропортом Кемпеговда.",
	'apollo-hospitals-jubilee-hills':
		"##history\nApollo Hospitals, Jubilee Hills, созданная в 1988 году, — флагманская больница Apollo в Хайдарабаде, имеет аккредитацию JCI. Была отмечена правительством Индии как ведущая больница медицинского туризма, получила FICCI Healthcare Excellence Award. В 2005 году внедрила первый в Индии сканер ПЭТ-КТ, провела первую в Индии коронарную ангиопластику с полностью рассасывающимся стентом, провела более 150 000 операций на сердце с заявленным показателем успеха выше 99%. Также выполнила более 700 кохлеарных имплантаций.\n##specialities\nБольница управляет 12 центрами передового опыта. Центр кардиологии располагает тремя катетеризационными лабораториями и отдельными кардиохирургическими операционными, с роботизированной кардиохирургией, TAVI и сложными коронарными вмешательствами. Онкологический центр опирается на 35-летний опыт и предлагает роботизированную онкохирургию. Неврология оснащена интраоперационной МРТ, нейронавигацией и позвоночной робототехникой. Трансплантологическая команда занимается пересадкой печени, почек, сердца и костного мозга, группа Apollo провела более 43 000 трансплантаций органов.\n##technology\nБольница располагает около 550 коек, аккредитована JCI, NABH и NABL. Находится по адресу Road No. 72, Film Nagar, Jubilee Hills.\n##international\nБольница проводит более 800 консультаций иностранных пациентов в месяц, с пациентами из таких стран, как США, ОАЭ, Танзания, Кения и Оман. Отдельная команда услуг для иностранных пациентов помогает с медицинскими визами, организацией поездки, проживанием и переводом.",
	'continental-hospitals':
		"##history\nContinental Hospitals основана в апреле 2013 года д-ром Guru N. Reddy в Финансовом округе Хайдарабада (Nanakramguda, Gachibowli). Это больница на 585 коек, занимающая 18 этажей и 1,4 миллиона квадратных футов, аккредитована JCI, NABH и NABL, первая в Индии больница узкой специализации с сертификацией LEED, с «зелёными» операционными и NICU и PICU 3 уровня. В 2022 году получила ASSOCHAM Award как лучшая больница Индии по внедрению технологий.\n##specialities\nБольница предлагает более 50 специальностей, известна сложными трансплантациями органов, кардиологией, неврологией, онкологией, гастроэнтерологией и ортопедией. В апреле 2023 года команда хирургов под руководством д-ра Pradeep Rachakonda и под руководством д-ра Sudhir Srivastava провела первую в Индии роботизированную операцию коронарного шунтирования (CABG) с роботом SSI Mantra. Трансплантологическое отделение занимается пересадкой печени, почек, сердца, лёгких и костного мозга, при поддержке продвинутых отделений интенсивной терапии и посттрансплантационной реабилитации.\n##technology\nБольница располагает 16 «зелёными» модульными операционными и 90 одноместными палатами интенсивной терапии, хирурги обучены работе на платформе da Vinci и других роботизированных платформах.\n##international\nContinental располагает отдельной зоной для иностранных пациентов и залом для медицинских обследований. Находится в Финансовом округе, рядом с ИТ-коридором Хайдарабада, примерно в 30–45 минутах от аэропорта.",
	'yashoda-hospitals-somajiguda':
		"##history\nYashoda Hospitals, Somajiguda, — первая больница группы Yashoda, начавшая работу в 1994 году после небольшой клиники, открытой в 1989 году д-ром G. Surendar Rao. За три десятилетия группа расширилась филиалами в Somajiguda, Secunderabad, Malakpet и Hitec City. Отделение в Somajiguda было признано AHPI больницей, дружелюбной к пациентам, а группа была признана правительством Индии первой в трупной трансплантации органов и первой среди многопрофильных больниц на Times Healthcare Achievers awards.\n##specialities\nБольница располагает более чем 400 койками, около 250 врачами и 500 медсёстрами. Центры передового опыта охватывают кардиохирургию и торакальную хирургию, неврологию, онкологию, трансплантацию печени и многоорганную трансплантацию, кости и суставы, нефрологию, робототехнику, хирургию позвоночника, охрану здоровья матери и ребёнка и лечение бесплодия, наряду с очень широким списком отделений — от ЛОР и гинекологии до пластической хирургии, ядерной медицины и бариатрической хирургии. Среди трансплантологических достижений группы — первая трансплантация лёгких в телугуязычных штатах (2012) и комбинированная трансплантация сердца и лёгких (2017).\n##technology\nЛаборатория, диагностические службы и аптека работают круглосуточно. Больница аккредитована NABH и первой в регионе внедрила роботизированную хирургию.\n##international\nYashoda предлагает услуги для иностранных пациентов, программа трансплантации входит в число ведущих многоорганных программ Индии, с мультидисциплинарной командой для диализа, заболеваний печени и почек и детских трансплантаций. Somajiguda находится на Raj Bhavan Road, в центре Хайдарабада.",
	'global-hospitals-hyderabad':
		"##history\nGleneagles Global Hospitals в Lakdi-ka-pul, известная как Global Hospitals, стала первой больницей Gleneagles Global, открытой в Хайдарабаде, и принадлежит Global Hospitals Group, основанной в 1999 году д-ром K. Ravindranath. Стала первопроходцем первой трансплантации сердца в бывших штатах Andhra Pradesh и Telangana, провела первую в регионе трансплантацию костного мозга и первую трансплантацию почки у близнецов, сообщает о первой успешной в Индии раздельной и вспомогательной трансплантации печени. По опросу Times of India 2021 года была признана вторым лучшим многопрофильным госпиталем Хайдарабада и вошла в топ-10 Южной Индии.\n##specialities\nБольница известна трансплантациями печени, почек, сердца и лёгких, также предлагает гепатологию, нефрологию, бариатрию, гастроэнтерологию, многоорганную трансплантацию, эстетическую и реконструктивную хирургию, онкологию, кардиологию, педиатрию, психиатрию, эндокринологию, ЛОР, ортопедию, хирургию позвоночника, гастроэнтерологию, общую и лапароскопическую хирургию и пульмонологию.\n##technology\nБольница располагает около 150 коек и шестью операционными, с роботизированными и малоинвазивными возможностями, а также несколькими отделениями интенсивной терапии, включая хирургическую, кардиохирургическую, промежуточную, печёночную интенсивную терапию и посттрансплантационные отделения. Аккредитована NABH и NABL.\n##international\nБольница предлагает поддержку иностранным пациентам через группу Gleneagles Global. Lakdi-ka-pul — центральное расположение в Хайдарабаде, рядом со станцией метро Lakdi-ka-pul.",
	'kims-hospitals-secunderabad':
		"##history\nKIMS Hospitals, Secunderabad, открылась в 2004 году как флагманская больница группы Krishna Institute of Medical Sciences, больница третичной и четвертичной помощи на 1000 коек, одна из крупнейших частных больниц Индии. Группа основана в 2000 году кардиоторакальным хирургом д-ром Bhaskar Rao Bollineni, который провёл более 30 000 операций за 25 лет и участвовал в разработке схемы Rajiv Gandhi Aarogyasri в 2007 году. Сегодня группа насчитывает более двух десятков больниц, а исполнительный директор и генеральный директор — д-р Abhinay Bollineni.\n##specialities\nБольница предлагает более 25 специальностей и узких специализаций, включая кардиологию, гастроэнтерологию и гепатологию, неврологию, трансплантацию органов, онкологию, ортопедию, урологию, лечение бесплодия, нефрологию и охрану здоровья матери и ребёнка. Центр неврологии занимается опухолями мозга, деформациями позвоночника, глубокой стимуляцией мозга при болезни Паркинсона и лечением инсульта, а центр KIMS Advanced Gastroenterology and Endoscopy (KAGE) лечит сложные заболевания пищеварения, болезни печени и процедуры POEM.\n##technology\nПрограмма трансплантации охватывает сердце, лёгкие, печень, почки и костный мозг, включая продвинутую перфузию ex vivo. Центр трансплантации сердца и лёгких провёл свою первую трансплантацию сердца в 2012 году и проводит около 75 трансплантаций сердца и лёгких в год, а в 2019 году больница зарегистрировала 1000 трансплантаций почек. Аккредитована NABH, имеет сертификат ISO 9001:2015.\n##international\nKIMS Secunderabad находится на Minister Road, в центре Секундерабада, рядом с железнодорожной станцией Secunderabad.",
};
